import React, { useState, useEffect } from 'react';
import { UserRole, MatchSession } from './types.ts';
import { storageService } from './services/storage.ts';
import AdminPanel from './components/AdminPanel.tsx';
import RefereePanel from './components/RefereePanel.tsx';
import ResultsBoard from './components/ResultsBoard.tsx';
import LoginModal from './components/LoginModal.tsx';

const App: React.FC = () => {
  const [role, setRole] = useState<UserRole>(UserRole.GUEST);
  const [activeTab, setActiveTab] = useState<'admin' | 'referee' | 'results'>('results');
  const [showLogin, setShowLogin] = useState<UserRole | null>(null);
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const isCloud = storageService.isCloudEnabled();

  // 使用實時訂閱模式
  useEffect(() => {
    const unsubscribe = storageService.subscribeSessions((updatedSessions) => {
      setSessions(updatedSessions);
    });
    return () => unsubscribe();
  }, []);

  const handleLogin = (targetRole: UserRole) => {
    if (role === targetRole) {
      if (targetRole === UserRole.ADMIN) setActiveTab('admin');
      if (targetRole === UserRole.REFEREE) setActiveTab('referee');
      return;
    }
    setShowLogin(targetRole);
  };

  const handleLogout = () => {
    setRole(UserRole.GUEST);
    setActiveTab('results');
  };

  const onLoginSuccess = (successRole: UserRole) => {
    setRole(successRole);
    setShowLogin(null);
    setActiveTab(successRole === UserRole.ADMIN ? 'admin' : 'referee');
  };

  const getRoleLabel = (r: UserRole) => {
    switch (r) {
      case UserRole.ADMIN: return '後台人員';
      case UserRole.REFEREE: return '裁判人員';
      default: return '一般選手/訪客';
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-indigo-700 text-white shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-2 cursor-pointer" onClick={() => setActiveTab('results')}>
            <i className="fas fa-trophy text-2xl text-yellow-400"></i>
            <h1 className="text-xl font-bold tracking-tight hidden sm:block">比賽紀錄系統</h1>
            {isCloud && (
              <span className="ml-2 flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-2 w-2 rounded-full bg-green-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
              </span>
            )}
          </div>

          <div className="flex items-center space-x-1 sm:space-x-4">
            <nav className="flex space-x-1">
              <button 
                onClick={() => setActiveTab('results')}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'results' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                比賽結果
              </button>
              <button 
                onClick={() => handleLogin(UserRole.REFEREE)}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'referee' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                裁判專區
              </button>
              <button 
                onClick={() => handleLogin(UserRole.ADMIN)}
                className={`px-3 py-2 rounded-md text-xs sm:text-sm font-medium transition ${activeTab === 'admin' ? 'bg-indigo-800' : 'hover:bg-indigo-600'}`}
              >
                後台管理
              </button>
            </nav>

            <div className="h-8 w-[1px] bg-indigo-500 mx-2 hidden sm:block"></div>

            <div className="flex items-center space-x-2">
               {role !== UserRole.GUEST && (
                 <button 
                  onClick={handleLogout}
                  className="bg-red-500 hover:bg-red-600 text-white w-8 h-8 rounded-full flex items-center justify-center transition shadow-sm"
                 >
                   <i className="fas fa-sign-out-alt text-xs"></i>
                 </button>
               )}
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8">
        <div className="mb-4 flex justify-between items-center text-xs">
          <div className="flex items-center text-gray-400">
            <i className={`fas fa-cloud mr-1 ${isCloud ? 'text-green-500' : 'text-gray-300'}`}></i>
            {isCloud ? '雲端即時同步中' : '本地儲存模式'}
          </div>
          <div className="font-bold text-gray-500">
            {getRoleLabel(role)}
          </div>
        </div>

        {activeTab === 'results' && (
          <ResultsBoard 
            sessions={sessions} 
            userRole={role} 
            onRefresh={() => {}} // 實時模式不需手動刷新
          />
        )}

        {activeTab === 'admin' && role === UserRole.ADMIN && (
          <AdminPanel onSessionCreated={() => {}} />
        )}

        {activeTab === 'referee' && role === UserRole.REFEREE && (
          <RefereePanel sessions={sessions} onResultSubmitted={() => {}} />
        )}

        {(activeTab === 'admin' || activeTab === 'referee') && role !== (activeTab === 'admin' ? UserRole.ADMIN : UserRole.REFEREE) && (
          <div className="text-center py-20 bg-white rounded-2xl shadow-sm border border-gray-100">
            <i className="fas fa-user-lock text-3xl text-indigo-200 mb-6"></i>
            <h2 className="text-2xl font-bold text-gray-800 mb-2">請先登入</h2>
            <button 
              onClick={() => handleLogin(activeTab === 'admin' ? UserRole.ADMIN : UserRole.REFEREE)}
              className="mt-4 bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold"
            >
              登入 {activeTab === 'admin' ? '管理員' : '裁判'} 帳號
            </button>
          </div>
        )}
      </main>

      {showLogin && (
        <LoginModal 
          targetRole={showLogin} 
          onClose={() => setShowLogin(null)} 
          onSuccess={onLoginSuccess} 
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface AdminPanelProps {
  onSessionCreated: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({ onSessionCreated }) => {
  const [sessions, setSessions] = useState<MatchSession[]>([]);
  const [editingSessionId, setEditingSessionId] = useState<string | null>(null);
  const [showShareModal, setShowShareModal] = useState<string | null>(null);

  const [title, setTitle] = useState('');
  const [refereeInput, setRefereeInput] = useState('');
  const [referees, setReferees] = useState<string[]>([]);
  const [tables, setTables] = useState<Partial<TableMatch>[]>([
    { tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }
  ]);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const formRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    loadSessions();
  }, []);

  const loadSessions = async () => {
    const data = await storageService.getSessions();
    setSessions(data);
  };

  const handleShare = (session: MatchSession) => {
    const code = storageService.generateShareCode(session);
    navigator.clipboard.writeText(code);
    setShowShareModal(code);
    alert('場次分享代碼已複製到剪貼簿！您可以傳送給裁判。');
  };

  const addReferee = () => {
    const rawInput = refereeInput.trim();
    if (!rawInput) return;
    const names = rawInput.split(/[,，]/).map(name => name.trim()).filter(name => name !== '');
    if (names.length > 0) {
      setReferees(prev => {
        const nextReferees = [...prev];
        names.forEach(name => {
          if (!nextReferees.includes(name)) nextReferees.push(name);
        });
        return nextReferees;
      });
      setRefereeInput('');
    }
  };

  const removeReferee = (name: string) => {
    setReferees(referees.filter(r => r !== name));
  };

  const addTable = () => {
    const nextNum = tables.length > 0 ? Math.max(...tables.map(t => t.tableNumber || 0)) + 1 : 1;
    setTables([...tables, { 
      tableNumber: nextNum, 
      player1: { id: '', name: '' }, 
      player2: { id: '', name: '' }, 
      result: GameResult.PENDING 
    }]);
  };

  const updateTable = (index: number, field: string, value: any) => {
    const newTables = [...tables];
    const target = { ...newTables[index] };
    if (field === 'p1Id') target.player1 = { ...target.player1!, id: value };
    else if (field === 'p1Name') target.player1 = { ...target.player1!, name: value };
    else if (field === 'p2Id') target.player2 = { ...target.player2!, id: value };
    else if (field === 'p2Name') target.player2 = { ...target.player2!, name: value };
    else if (field === 'tableNumber') target.tableNumber = parseInt(value) || 0;
    newTables[index] = target;
    setTables(newTables);
  };

  const removeTable = (index: number) => {
    setTables(tables.filter((_, i) => i !== index));
  };

  const handleExcelImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(worksheet) as any[];

        const importedTables: Partial<TableMatch>[] = jsonData.map((row: any, idx) => ({
          tableNumber: row['桌號'] || row['Table'] || (idx + 1),
          player1: { id: String(row['先手ID'] || row['P1 ID'] || ''), name: String(row['先手姓名'] || row['P1 Name'] || '') },
          player2: { id: String(row['後手ID'] || row['P2 ID'] || ''), name: String(row['後手姓名'] || row['P2 Name'] || '') },
          result: GameResult.PENDING
        }));
        setTables(importedTables);
        if (fileInputRef.current) fileInputRef.current.value = '';
      } catch (err) {
        alert('解析 Excel 失敗');
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportExcel = (session: MatchSession) => {
    const exportData = session.tables.map(t => ({
      '桌號': t.tableNumber,
      '先手ID': t.player1.id,
      '先手姓名': t.player1.name,
      '後手ID': t.player2.id,
      '後手姓名': t.player2.name,
      '結果': t.result,
      '送出裁判': t.submittedBy || '',
      '更新時間': t.updatedAt ? new Date(t.updatedAt).toLocaleString() : ''
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, '比賽結果');
    XLSX.writeFile(workbook, `${session.title}_比賽結果.xlsx`);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title) return alert('請輸入場次標題');
    if (referees.length === 0) return alert('請至少輸入一位裁判人員');

    const sessionData = {
      title,
      referees,
      tables: tables.map(t => ({
        ...t,
        tableNumber: t.tableNumber || 0,
        player1: t.player1 || { id: '', name: '' },
        player2: t.player2 || { id: '', name: '' },
        result: t.result || GameResult.PENDING
      } as TableMatch))
    };

    if (editingSessionId) {
      const existing = sessions.find(s => s.id === editingSessionId);
      if (existing) await storageService.updateSession({ ...existing, ...sessionData });
      alert('場次已更新並發布至雲端');
    } else {
      await storageService.addSession({ 
        id: uuidv4(), 
        status: MatchStatus.OPEN, 
        createdAt: new Date().toISOString(), 
        ...sessionData 
      });
      alert('場次已成功創建並發布');
    }
    resetForm();
    onSessionCreated();
    await loadSessions();
  };

  const resetForm = () => {
    setTitle(''); setReferees([]); setEditingSessionId(null);
    setTables([{ tableNumber: 1, player1: { id: '', name: '' }, player2: { id: '', name: '' }, result: GameResult.PENDING }]);
  };

  const startEdit = (session: MatchSession) => {
    setEditingSessionId(session.id);
    setTitle(session.title);
    setReferees(session.referees);
    setTables(session.tables);
    formRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('確定刪除此比賽場次？此動作將同步影響所有設備。')) {
      await storageService.deleteSession(id);
      await loadSessions();
      onSessionCreated();
      if (editingSessionId === id) resetForm();
    }
  };

  return (
    <div className="space-y-12 max-w-5xl mx-auto pb-20">
      <section className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="bg-slate-50 px-6 py-4 border-b flex justify-between items-center">
          <h2 className="text-xl font-bold text-slate-800 flex items-center">
            <i className="fas fa-tasks text-indigo-500 mr-2"></i>
            現有比賽場次
          </h2>
          <div className="flex items-center space-x-2">
            <span className="bg-indigo-100 text-indigo-600 px-3 py-1 rounded-full text-xs font-bold">
              共 {sessions.length} 場
            </span>
          </div>
        </div>
        <div className="divide-y divide-gray-50">
          {sessions.length > 0 ? sessions.map(session => (
            <div key={session.id} className="p-5 flex flex-col md:flex-row justify-between items-center hover:bg-slate-50 transition gap-4">
              <div className="flex-grow text-center md:text-left">
                <h3 className="font-bold text-slate-800 text-lg">{session.title}</h3>
                <div className="flex flex-wrap justify-center md:justify-start gap-2 mt-2">
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${session.status === MatchStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                    {session.status === MatchStatus.OPEN ? '開放中' : '已截止'}
                  </span>
                  <span className="text-[10px] text-gray-400">桌數: {session.tables.length}</span>
                </div>
              </div>
              <div className="flex space-x-1">
                <button onClick={() => handleShare(session)} className="p-2.5 text-blue-600 hover:bg-blue-50 rounded-lg transition" title="複製分享代碼給裁判">
                  <i className="fas fa-share-alt text-xl"></i>
                </button>
                <button onClick={() => handleExportExcel(session)} className="p-2.5 text-emerald-600 hover:bg-emerald-50 rounded-lg transition" title="匯出 Excel">
                  <i className="fas fa-file-excel text-xl"></i>
                </button>
                <button onClick={() => startEdit(session)} className="p-2.5 text-indigo-600 hover:bg-indigo-50 rounded-lg transition" title="修改">
                  <i className="fas fa-edit text-xl"></i>
                </button>
                <button onClick={() => handleDelete(session.id)} className="p-2.5 text-red-500 hover:bg-red-50 rounded-lg transition" title="刪除">
                  <i className="fas fa-trash-alt text-xl"></i>
                </button>
              </div>
            </div>
          )) : (
            <div className="py-20 text-center text-gray-400 italic">尚未建立任何比賽場次</div>
          )}
        </div>
      </section>

      <div ref={formRef} className="bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
        <h2 className="text-2xl font-black text-slate-800 mb-8 flex items-center">
          <i className={`fas ${editingSessionId ? 'fa-pen-nib text-amber-500' : 'fa-plus-circle text-indigo-500'} mr-3`}></i>
          {editingSessionId ? '編輯比賽場次' : '建立全新比賽場次'}
        </h2>

        <form onSubmit={handleSubmit} className="space-y-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">場次標題</label>
              <input 
                type="text" 
                value={title} 
                onChange={(e) => setTitle(e.target.value)} 
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                placeholder="例如：2024 夏季杯複賽" 
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-bold text-slate-600">裁判名單 (逗號分隔)</label>
              <div className="flex space-x-2">
                <input 
                  type="text" 
                  value={refereeInput} 
                  onChange={(e) => setRefereeInput(e.target.value)} 
                  onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addReferee())}
                  className="flex-grow px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition" 
                  placeholder="輸入姓名並按新增" 
                />
                <button type="button" onClick={addReferee} className="bg-slate-800 text-white px-6 rounded-xl font-bold hover:bg-slate-700 transition">新增</button>
              </div>
              <div className="flex flex-wrap gap-2 pt-2">
                {referees.map(r => (
                  <span key={r} className="inline-flex items-center px-3 py-1 rounded-full text-xs font-bold bg-indigo-50 text-indigo-700 border border-indigo-100">
                    {r}
                    <button type="button" onClick={() => removeReferee(r)} className="ml-2 hover:text-red-500">
                      <i className="fas fa-times-circle"></i>
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <h3 className="text-lg font-bold text-slate-800">桌次與對手設定</h3>
              <div className="flex space-x-3">
                <input type="file" ref={fileInputRef} onChange={handleExcelImport} accept=".xlsx,.xls" className="hidden" />
                <button type="button" onClick={() => fileInputRef.current?.click()} className="text-emerald-600 bg-emerald-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-emerald-100 transition">
                  <i className="fas fa-file-import mr-2"></i>匯入 Excel
                </button>
                <button type="button" onClick={addTable} className="text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg text-sm font-bold hover:bg-indigo-100 transition">
                  <i className="fas fa-plus mr-2"></i>新增一桌
                </button>
              </div>
            </div>

            <div className="overflow-x-auto border rounded-2xl">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr className="text-left text-slate-500 font-bold uppercase">
                    <th className="px-4 py-3 w-20">桌號</th>
                    <th className="px-4 py-3">先手 (ID / 姓名)</th>
                    <th className="px-4 py-3">後手 (ID / 姓名)</th>
                    <th className="px-4 py-3 w-16 text-center">刪</th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {tables.map((table, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition">
                      <td className="px-4 py-3">
                        <input type="number" value={table.tableNumber} onChange={(e) => updateTable(idx, 'tableNumber', e.target.value)} className="w-full p-2 border rounded-lg focus:ring-1 focus:ring-indigo-400 outline-none" />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="ID" value={table.player1?.id} onChange={(e) => updateTable(idx, 'p1Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player1?.name} onChange={(e) => updateTable(idx, 'p1Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex space-x-2">
                          <input type="text" placeholder="ID" value={table.player2?.id} onChange={(e) => updateTable(idx, 'p2Id', e.target.value)} className="w-20 p-2 border rounded-lg text-xs" />
                          <input type="text" placeholder="姓名" value={table.player2?.name} onChange={(e) => updateTable(idx, 'p2Name', e.target.value)} className="w-full p-2 border rounded-lg text-xs" />
                        </div>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <button type="button" onClick={() => removeTable(idx)} className="text-red-400 hover:text-red-600 p-2">
                          <i className="fas fa-trash"></i>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t">
            <button type="submit" className={`flex-grow py-4 rounded-2xl font-black text-lg text-white shadow-xl transition active:scale-95 ${editingSessionId ? 'bg-amber-500 hover:bg-amber-600 shadow-amber-200' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'}`}>
              {editingSessionId ? '確認儲存修改' : '建立比賽場次'}
            </button>
            {editingSessionId && (
              <button type="button" onClick={resetForm} className="bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-bold hover:bg-slate-200 transition">
                取消編輯
              </button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminPanel;

import React, { useState, useEffect } from 'react';
import { MatchSession, MatchStatus, TableMatch, GameResult } from '../types.ts';
import { storageService } from '../services/storage.ts';

interface RefereePanelProps {
  sessions: MatchSession[];
  onResultSubmitted: () => void;
}

const RefereePanel: React.FC<RefereePanelProps> = ({ sessions, onResultSubmitted }) => {
  const [refereeName, setRefereeName] = useState('');
  const [selectedSessionId, setSelectedSessionId] = useState('');
  const [selectedTableNumber, setSelectedTableNumber] = useState<number | ''>('');
  const [result, setResult] = useState<GameResult>(GameResult.PENDING);
  const [importCode, setImportCode] = useState('');
  const [showImport, setShowImport] = useState(false);

  const currentSession = sessions.find(s => s.id === selectedSessionId);
  const currentTable = currentSession?.tables.find(t => t.tableNumber === selectedTableNumber);

  useEffect(() => {
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
    setRefereeName('');
  }, [selectedSessionId]);

  const handleImport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!importCode) return;
    const session = await storageService.importFromCode(importCode);
    if (session) {
      alert(`成功載入場次：${session.title}`);
      setSelectedSessionId(session.id);
      setImportCode('');
      setShowImport(false);
      onResultSubmitted(); 
    } else {
      alert('無效的代碼，請重新檢查。');
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentSession) return alert('請選擇比賽場次');
    if (!refereeName) return alert('請先選擇您的姓名');
    if (currentSession.status !== MatchStatus.OPEN) return alert('此場次已截止');
    if (selectedTableNumber === '') return alert('請選擇桌號');
    if (result === GameResult.PENDING) return alert('請選擇結果');

    const updatedTables = currentSession.tables.map(t => {
      if (t.tableNumber === selectedTableNumber) {
        return {
          ...t,
          result,
          submittedBy: refereeName,
          updatedAt: new Date().toISOString()
        };
      }
      return t;
    });

    storageService.updateSession({
      ...currentSession,
      tables: updatedTables
    });

    onResultSubmitted();
    alert('結果已成功同步更新！');
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  };

  return (
    <div className="max-w-xl mx-auto space-y-6">
      <div className="bg-white rounded-xl shadow-md p-6 border border-emerald-100">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-gray-800 flex items-center">
            <i className="fas fa-clipboard-check text-emerald-500 mr-2"></i>
            裁判結果回報
          </h2>
          <button 
            onClick={() => setShowImport(!showImport)}
            className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1 rounded-full hover:bg-blue-100 transition"
          >
            {showImport ? '取消導入' : '載入新場次代碼'}
          </button>
        </div>

        {showImport && (
          <form onSubmit={handleImport} className="mb-8 p-4 bg-blue-50 rounded-xl border border-blue-100 animate-in fade-in zoom-in duration-300">
            <label className="block text-sm font-bold text-blue-700 mb-2">請貼上後台提供的場次代碼</label>
            <textarea 
              value={importCode}
              onChange={(e) => setImportCode(e.target.value)}
              className="w-full p-3 text-xs border rounded-lg mb-3 h-24 font-mono"
              placeholder="貼上代碼..."
            />
            <button type="submit" className="w-full py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition">
              確認載入比賽資訊
            </button>
          </form>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">選擇比賽場次</label>
            <select 
              value={selectedSessionId}
              onChange={(e) => setSelectedSessionId(e.target.value)}
              className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition bg-white"
            >
              <option value="">-- 請選擇場次 --</option>
              {sessions.map(s => (
                <option key={s.id} value={s.id}>
                  {s.title} {s.status === MatchStatus.CLOSED ? '(已截止)' : ''}
                </option>
              ))}
            </select>
          </div>

          {selectedSessionId && currentSession && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <label className="block text-sm font-semibold text-gray-700 mb-1">您的姓名</label>
              <select 
                value={refereeName}
                onChange={(e) => setRefereeName(e.target.value)}
                className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition bg-white"
              >
                <option value="">-- 請選擇您的姓名 --</option>
                {currentSession.referees.map(r => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
            </div>
          )}

          {selectedSessionId && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-400">
              <label className="block text-sm font-semibold text-gray-700 mb-1">選擇桌號</label>
              <select 
                value={selectedTableNumber}
                onChange={(e) => setSelectedTableNumber(parseInt(e.target.value))}
                className="w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-emerald-500 outline-none transition bg-white"
              >
                <option value="">-- 請選擇桌號 --</option>
                {currentSession?.tables.map(t => (
                  <option key={t.tableNumber} value={t.tableNumber}>
                    第 {t.tableNumber} 桌 ({t.player1.name} vs {t.player2.name})
                  </option>
                ))}
              </select>
            </div>
          )}

          {currentTable && (
            <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-100 animate-in zoom-in duration-300">
              <p className="text-xs text-emerald-600 font-bold uppercase tracking-wider mb-2">對弈資訊</p>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-xs text-gray-500">先手 (P1)</p>
                  <p className="font-bold text-gray-800">{currentTable.player1.name}</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">後手 (P2)</p>
                  <p className="font-bold text-gray-800">{currentTable.player2.name}</p>
                </div>
              </div>
            </div>
          )}

          {currentTable && (
            <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
              <label className="block text-sm font-semibold text-gray-700 mb-3">比賽結果 (先手狀態)</label>
              <div className="grid grid-cols-3 gap-3">
                {[GameResult.WIN, GameResult.LOSS, GameResult.DRAW].map(res => (
                  <button
                    key={res}
                    type="button"
                    onClick={() => setResult(res)}
                    className={`py-3 rounded-lg font-bold border-2 transition ${
                      result === res 
                        ? 'bg-emerald-600 text-white border-emerald-600 shadow-md' 
                        : 'bg-white text-gray-600 border-gray-200 hover:border-emerald-200'
                    }`}
                  >
                    {res}
                  </button>
                ))}
              </div>
            </div>
          )}

          <button 
            type="submit"
            disabled={!currentTable || currentSession?.status === MatchStatus.CLOSED}
            className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition active:scale-95 flex items-center justify-center space-x-2 ${
              currentSession?.status === MatchStatus.CLOSED 
                ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                : 'bg-emerald-600 text-white hover:bg-emerald-700'
            }`}
          >
            <i className="fas fa-save"></i>
            <span>儲存並同步結果</span>
          </button>
        </form>
      </div>
    </div>
  );
};

