  useEffect(() => {
    setSelectedTableNumber('');
    setResult(GameResult.PENDING);
  }, [selectedSessionId]);

  const handleNameSelect = (name: string) => {
    setRefereeName(name);
    localStorage.setItem(STORAGE_NAME_KEY, name);
  };

